CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK (length(full_name)<=160), preferred_language text NOT NULL DEFAULT 'en' CHECK (preferred_language IN ('en','fr')), avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(full_name,preferred_language,avatar_path) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid()); CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','editor','member')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.role_permissions(role text NOT NULL, permission text NOT NULL, PRIMARY KEY(role,permission)); GRANT SELECT ON public.role_permissions TO authenticated; GRANT ALL ON public.role_permissions TO service_role; ALTER TABLE public.role_permissions ENABLE ROW LEVEL SECURITY; CREATE POLICY read_permissions ON public.role_permissions FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.has_role(_user_id uuid,_role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated,service_role;
CREATE FUNCTION public.has_permission(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.role_permissions p ON p.role=r.role WHERE r.user_id=auth.uid() AND p.permission=_permission) $$;
REVOKE ALL ON FUNCTION public.has_permission(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_permission(text) TO authenticated,service_role;
CREATE TABLE public.content_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), page text NOT NULL CHECK(page IN ('home','about','services','savings','loans','activities','news','membership','contact','legal')), title_en text NOT NULL DEFAULT '' CHECK(length(title_en)<=180), title_fr text NOT NULL DEFAULT '' CHECK(length(title_fr)<=180), body_en text NOT NULL DEFAULT '' CHECK(length(body_en)<=20000), body_fr text NOT NULL DEFAULT '' CHECK(length(body_fr)<=20000), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), created_by uuid NOT NULL REFERENCES public.profiles(id), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.content_entries TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.content_entries TO authenticated; GRANT ALL ON public.content_entries TO service_role; ALTER TABLE public.content_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_content ON public.content_entries FOR SELECT TO anon,authenticated USING(status='published'); CREATE POLICY editors_read ON public.content_entries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_permission('content.write')); CREATE POLICY editors_create ON public.content_entries FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_permission('content.write'))); CREATE POLICY editors_update ON public.content_entries FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_permission('content.write')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_permission('content.write')); CREATE POLICY admins_delete ON public.content_entries FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid, action text NOT NULL, entity text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.audit_logs_id_seq TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY admin_audit ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,entity,entity_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,coalesce(to_jsonb(NEW)->>'id',to_jsonb(OLD)->>'id')); IF TG_TABLE_NAME='content_entries' AND TG_OP='UPDATE' THEN NEW.updated_at=now(); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_profile BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_content BEFORE INSERT OR UPDATE OR DELETE ON public.content_entries FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_roles BEFORE INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_change(); CREATE TRIGGER audit_permissions BEFORE INSERT OR UPDATE OR DELETE ON public.role_permissions FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE FUNCTION public.create_member_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,preferred_language) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),160),CASE WHEN NEW.raw_user_meta_data->>'preferred_language'='fr' THEN 'fr' ELSE 'en' END); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'member'); RETURN NEW; END $$; CREATE TRIGGER on_member_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_member_profile();
REVOKE ALL ON FUNCTION public.create_member_profile() FROM PUBLIC; REVOKE ALL ON FUNCTION public.audit_change() FROM PUBLIC;
CREATE TABLE public.account_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), kind text NOT NULL CHECK(kind IN ('export','deletion')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.account_requests TO authenticated; GRANT ALL ON public.account_requests TO service_role; ALTER TABLE public.account_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY own_requests ON public.account_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY request_account_action ON public.account_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='pending'); CREATE TRIGGER audit_requests BEFORE INSERT OR UPDATE ON public.account_requests FOR EACH ROW EXECUTE FUNCTION public.audit_change();
CREATE TABLE public.ai_access_state(id text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, status integer, message text, updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.ai_access_state TO service_role; ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ai_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.ai_usage TO authenticated; GRANT ALL ON public.ai_usage TO service_role; ALTER TABLE public.ai_usage ENABLE ROW LEVEL SECURITY; CREATE POLICY own_ai_usage ON public.ai_usage FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.reserve_ai_request() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RETURN false; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF (SELECT count(*) FROM public.ai_usage WHERE user_id=auth.uid() AND created_at>now()-interval '1 hour')>=10 THEN RETURN false; END IF; INSERT INTO public.ai_usage(user_id) VALUES(auth.uid()); RETURN true; END $$; REVOKE ALL ON FUNCTION public.reserve_ai_request() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_ai_request() TO authenticated;
CREATE INDEX ai_usage_user_time ON public.ai_usage(user_id,created_at);